 void renderFolders(){sidebar.removeAllViews();TextView label=text("사진 폴더",13,MUTED);sidebar.addView(label,lp(-1,36));String base=demo?"":config.root;List<String> sorted=new ArrayList<>(folders);sorted.remove(base);sorted.sort(Paths::natural);sorted.add(0,base);ListView list=new ListView(this);list.setDivider(null);list.setAdapter(new BaseAdapter(){public int getCount(){return sorted.size();}public Object getItem(int position){return sorted.get(position);}public long getItemId(int position){return position;}public View getView(int position,View old,ViewGroup parent){String f=sorted.get(position);String relative=base.isEmpty()?f:f.substring(Math.min(f.length(),base.length()+1));String name=position==0?"전체 선택":f.substring(f.lastIndexOf('/')+1);return folderRow(f,name,position==0?0:Math.min(3,Paths.depth(relative)-1)+1);}});sidebar.addView(list,new LinearLayout.LayoutParams(-1,0,1));CheckBox recursive=new CheckBox(this);recursive.setText("하위 폴더 포함");recursive.setTextSize(13);recursive.setTextColor(MUTED);recursive.setChecked(selection.recursive);recursive.setPadding(0,dp(10),0,0);recursive.setOnCheckedChangeListener((b,on)->{selection.recursive=on;saveSelection();renderFolders();refreshSelection();});sidebar.addView(recursive,lp(-1,52));}
 View folderRow(String path,String name,int indent){int state=selection.state(path,folders);LinearLayout r=row();r.setPadding(dp(4+indent*12),0,dp(4),0);View check=new View(this){final Paint paint=new Paint(3);final Path tick=new Path();protected void onDraw(Canvas c){super.onDraw(c);float pad=dp(3),size=Math.min(getWidth(),getHeight())-pad*2;paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1.4f));paint.setColor(state==0?MUTED:GREEN);c.drawRect(pad,pad,pad+size,pad+size,paint);if(state!=0){paint.setStyle(Paint.Style.FILL);c.drawRect(pad,pad,pad+size,pad+size,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));paint.setColor(Color.WHITE);if(state==2)c.drawLine(pad+size*.2f,pad+size*.5f,pad+size*.8f,pad+size*.5f,paint);else{Path t=tick;t.reset();t.moveTo(pad+size*.18f,pad+size*.5f);t.lineTo(pad+size*.42f,pad+size*.73f);t.lineTo(pad+size*.84f,pad+size*.22f);c.drawPath(t,paint);}}}};r.addView(check,lp(24,24));TextView label=text(name,14,INK);label.setSingleLine();label.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams labelParams=new LinearLayout.LayoutParams(0,-1,1);labelParams.leftMargin=dp(8);r.addView(label,labelParams);r.setBackground(shape(state==1?Color.rgb(232,237,228):BG,false));r.setOnClickListener(v->{if(indent==0){selection.rules.clear();if(!selection.recursive){for(String f:folders)selection.rules.put(f,state!=1);}else selection.all(path,state!=1);}else selection.set(path,state!=1);saveSelection();renderFolders();refreshSelection();});r.setFocusable(true);r.setContentDescription(name+" · "+(state==1?"선택됨":state==2?"일부 선택됨":"선택 안 됨"));r.setLayoutParams(new AbsListView.LayoutParams(-1,dp(48)));return r;}
 List<Photo> selected(){List<Photo> a=selection.filter(all);return !online&&!demo?images.cached(a):a;}
