 void togglePause(){paused=!paused;LinearLayout r=(LinearLayout)toolbar.getChildAt(1);((Button)r.getChildAt(2)).setText(paused?"계속 보기":"일시정지");ui.removeCallbacks(slide);if(!paused)ui.postDelayed(slide,seconds*1000L);showControls();}
 void toggleControls(){if(toolbar.getVisibility()==View.VISIBLE&&!paused)toolbar.setVisibility(View.GONE);else showControls();}
 void showControls(){if(toolbar==null)return;toolbar.setVisibility(View.VISIBLE);ui.removeCallbacks(hideControls);if(!paused)ui.postDelayed(hideControls,3000);}
 void advance(boolean previous){if(!playing||playlist==null)return;ui.removeCallbacks(slide);if(previous)playlist.previous();else playlist.next(selected());loadCurrent();}
 Photo lookup(String path){for(Photo p:all)if(p.path.equals(path))return p;return null;}
 void loadCurrent(){if(!playing||playlist==null)return;String path=playlist.current();if(path==null){emptyPlayback();return;}Photo p=lookup(path);if(p==null){playlist.reconcile(selected());if(playlist.current()==null){emptyPlayback();return;}p=lookup(playlist.current());}if(p==null){emptyPlayback();return;}final Photo photo=p;int token=++loadToken,gen=generation;picture.setTag(photo.path);loading.setVisibility(View.VISIBLE);updatePlayerInfo();savePlaylist();Images loader=images;decode.execute(()->{if(token!=loadToken||gen!=generation)return;Images.Decoded decoded=null;Throwable error=null;try{decoded=loader.decode(photo,1920,1200);}catch(Throwable e){error=e;}Images.Decoded result=decoded;Throwable fail=error;ui.post(()->{if(token!=loadToken||gen!=generation||!playing){if(result!=null)result.bitmap.recycle();return;}loading.setVisibility(View.GONE);if(result!=null){Bitmap old=shown;shown=result.bitmap;picture.setImageBitmap(shown);if(old!=null&&old!=shown)old.recycle();bad.remove(photo.path);updatePlayerInfo(result.note);ui.removeCallbacks(slide);if(!paused&&visible)ui.postDelayed(slide,seconds*1000L);}else{bad.add(photo.path);String kind=SmbSource.kind(fail);if(kind.equals("AUTH")||kind.equals("DENIED")){failure=kind;online=false;images.online=false;ui.removeCallbacks(poll);paused=true;showStatus("계정 또는 폴더를 확인해 주세요",kind);return;}if(fail instanceof Images.TransportFailure&&kind.equals("OFFLINE")){online=false;images.online=false;offlineChoice=false;failure="OFFLINE";paused=true;showStatus("PC에 연결할 수 없습니다","OFFLINE");restartPoll();return;}if(kind.equals("MISSING")){all.remove(photo);db.remove(photo.path);playlist.reconcile(selected());}playerInfo.setText("표시할 수 없는 사진 · "+photo.name()+"\n"+formatReason(fail));showControls();if(bad.size()>=playlist.order.size()||playlist.order.isEmpty()){paused=true;new AlertDialog.Builder(this).setTitle("표시할 사진을 찾지 못했습니다").setMessage("형식·파일 상태 또는 연결을 확인해 주세요. 원본 파일은 변경하지 않았습니다.").setPositiveButton("사진함",(d,w)->gallery()).setNegativeButton("다시 시도",(d,w)->{bad.clear();paused=false;loadCurrent();}).show();}else ui.postDelayed(()->{if(playing&&token==loadToken)advance(false);},1500);}});});}
 String formatReason(Throwable t){String s=String.valueOf(t);if(s.contains("RAW_PREVIEW"))return "RAW 미리보기 또는 인코딩 미지원";if(s.contains("FORMAT_UNSUPPORTED"))return "지원되지 않는 형식/인코딩";if(s.contains("FILE_CHANGED"))return "파일이 갱신되었습니다 · 다시 스캔해 주세요";if(s.contains("FILE_LIMIT"))return "파일 크기 제한 (256MB)";if(t instanceof OutOfMemoryError)return "메모리 부족 · 다음 사진으로 이동";return "파일 읽기 또는 네트워크 오류";}
 void updatePlayerInfo(){updatePlayerInfo("");}void updatePlayerInfo(String note){if(playing&&playerInfo!=null&&playlist!=null)playerInfo.setText((demo?"체험 사진 · ":!online?"PC 연결 안 됨 · 저장된 사진 · ":"")+(playlist.index+1)+" / "+playlist.order.size()+"   ·   "+(playlist.random?"랜덤":"파일명 순")+"   ·   "+seconds+"초\n"+(playlist.current()==null?"":playlist.current())+(note.isEmpty()?"":"  ·  "+note));}
